                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        return A

    def rank(A):
        A = gaussian_elimination(A)
        r = 0
        for row in A:
            if any(row):
                r += 1
        return r

    def read_twice_branching_program(n):
        program = []
        for _ in range(n):
            state = random.randint(0, 1)
            transition = random.choice(['left', 'right'])
            program.append((state, transition))
        return program

